import axios from "axios";
export const A_Z = 'A_Z';
export const Z_A = 'Z_A';
export const WEIGHT_MAX = 'WEIGHT_MAX';
export const WEIGHT_MIN = 'WEIGHT_MIN';

export function getDogs() {
  return async (dispatch) => {
    try {
        var dog = await axios('http://localhost:3001/dogs');
        return dispatch({
            type: 'GET_DOGS',
            payload: dog.data
           
        })
    } catch (error) {
        console.log(error);
    }

}
}


export const getTemperaments = () => {
  return async function (dispatch) {
    const json = await axios.get("http://localhost:3001/temperaments", {});
    return dispatch({
      type: "GET_TEMPERAMENTS",
      payload: json.data,
    });
  };
}

export const getByName = (name)=> async dispatch => {
  try{
    await axios.get('http://localhost:3001/dogs?name='+ name)
    .then((response) => {
        dispatch({
            type: 'GET_BY_NAME',
            payload: response.data
        })
    })
 } catch (error) { 
    return alert("Raza no encontrada")
 }
}

export function getDetail(id){
  return async function (dispatch){
    try {
      const idDog = await axios("http://localhost:3001/dogs/" + id)
      return dispatch({
        type: "GET_DETAIL", 
        payload: idDog.data
      })
  
    } catch (error) {
      console.log(error)
    }
   }
  }


export function filterBreed(payload){
  return{
      type: 'FILTER_BREED',
      payload
  }
}


export function filterTemperament(arrayTemps){
  return async function (dispatch) {
    try {
      const json = await axios.get("http://localhost:3001/dogs");
      let array = [];
      arrayTemps.forEach((t) => {
        json.data.forEach((el) => {
          if (el.temps && el.temps.includes(t)) array.push(el);

        });
      });
      let finalArray = [];
      array.forEach((el) => {
        if (finalArray.length !== 0) {
          let count = 0;
          finalArray.forEach((dogs) => {
            if (dogs.id == el.id) count++;
          });
          if (count == 0) finalArray.push(el);
        } else {
          finalArray.push(el);
        }
      });
      return dispatch({
        type: "FILTER_TEMPERAMENT",
        payload: finalArray,
      });
    } catch (error) {
      console.log(error);
    }
  };
}
export function orderBy(order) {
  return function (dispatch) {
    dispatch({ type: 'ORDER_BY', payload: order });
    };
}

export function clean(){
  return function(dispatch){
    dispatch({type:'CLEAN'})
  }
}
